import {
  proposeAction, approveProposal, rejectProposal, executeProposal,
  getProposal, listPendingProposals, sweepExpiredProposals, clearProposalsForTesting,
} from './four-eyes-approval.ts';

let failed = 0;
async function check(name: string, fn: () => Promise<void> | void) {
  try { await fn(); console.log(`  ✓ ${name}`); }
  catch (e) { failed++; console.error(`  ✗ ${name}\n      ${(e as Error).message}`); }
}
function assert(cond: unknown, msg: string) { if (!cond) throw new Error(msg); }
function eq<T>(a: T, b: T, msg: string) { if (a !== b) throw new Error(`${msg}: expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`); }

(async () => {
  console.log('\nProposal lifecycle (happy path)');
  await check('propose → approve (different admin) → execute', async () => {
    await clearProposalsForTesting();
    const p = await proposeAction({
      kind: 'regulator.exportPack',
      requesterId: 'admin-1',
      payload: { tenantId: 't1', windowMs: 30 * 24 * 60 * 60 * 1000 },
    });
    assert(p.ok, 'propose ok');
    eq(p.proposal.state, 'pending_approval', 'pending');

    const a = await approveProposal(p.proposal.id, 'admin-2');
    assert(a.ok, 'approve ok');
    eq(a.proposal.state, 'ready_to_execute', 'ready');

    const e = await executeProposal(p.proposal.id, 'admin-1');
    assert(e.ok, 'execute ok');
    eq(e.proposal.state, 'executed', 'executed');
  });

  console.log('\nRejection + isolation invariants');
  await check('approver MUST differ from requester (4-eyes)', async () => {
    await clearProposalsForTesting();
    const p = await proposeAction({
      kind: 'regulator.exportPack', requesterId: 'admin-1',
      payload: { tenantId: 't1' },
    });
    assert(p.ok, 'propose');
    const a = await approveProposal(p.proposal.id, 'admin-1');  // same person
    eq(a.ok, false, 'should reject self-approval');
    if (!a.ok) assert(/4-eyes/.test(a.reason), `reason: ${a.reason}`);
  });

  await check('cannot execute before approval', async () => {
    await clearProposalsForTesting();
    const p = await proposeAction({
      kind: 'regulator.exportPack', requesterId: 'admin-1',
      payload: { tenantId: 't1' },
    });
    assert(p.ok, '');
    const e = await executeProposal(p.proposal.id, 'admin-1');
    eq(e.ok, false, 'should reject');
    if (!e.ok) assert(/not ready_to_execute/.test(e.reason), `reason: ${e.reason}`);
  });

  await check('cannot approve twice (idempotent rejection)', async () => {
    await clearProposalsForTesting();
    const p = await proposeAction({ kind: 'regulator.exportPack', requesterId: 'admin-1', payload: {} });
    assert(p.ok, '');
    const a1 = await approveProposal(p.proposal.id, 'admin-2');
    assert(a1.ok, 'first approval ok');
    const a2 = await approveProposal(p.proposal.id, 'admin-3');
    eq(a2.ok, false, 'second approval should reject');
  });

  await check('only requester or approver can execute', async () => {
    await clearProposalsForTesting();
    const p = await proposeAction({ kind: 'regulator.exportPack', requesterId: 'admin-1', payload: {} });
    assert(p.ok, '');
    await approveProposal(p.proposal.id, 'admin-2');
    const e = await executeProposal(p.proposal.id, 'admin-3');  // outsider
    eq(e.ok, false, 'should reject');
    if (!e.ok) assert(/requester or approver/.test(e.reason), `reason: ${e.reason}`);
  });

  await check('rejection is terminal', async () => {
    await clearProposalsForTesting();
    const p = await proposeAction({ kind: 'regulator.exportPack', requesterId: 'admin-1', payload: {} });
    assert(p.ok, '');
    const r = await rejectProposal(p.proposal.id, 'admin-2', 'looks suspicious');
    assert(r.ok, 'reject ok');
    eq(r.proposal.state, 'rejected', 'rejected');
    const a = await approveProposal(p.proposal.id, 'admin-3');
    eq(a.ok, false, 'cannot approve after reject');
  });

  console.log('\nExpiry');
  await check('proposal expires after 24h', async () => {
    await clearProposalsForTesting();
    const p = await proposeAction({
      kind: 'regulator.exportPack', requesterId: 'admin-1', payload: {},
      expiryMs: 1, // immediate expiry
    });
    assert(p.ok, '');
    await new Promise((r) => setTimeout(r, 5));
    const swept = await sweepExpiredProposals();
    assert(swept >= 1, `should sweep at least 1, got ${swept}`);
    const a = await approveProposal(p.proposal.id, 'admin-2');
    eq(a.ok, false, 'cannot approve expired');
  });

  console.log('\nList + state queries');
  await check('listPendingProposals returns only pending', async () => {
    await clearProposalsForTesting();
    const p1 = await proposeAction({ kind: 'regulator.exportPack', requesterId: 'admin-1', payload: { id: 'a' } });
    const p2 = await proposeAction({ kind: 'regulator.exportPack', requesterId: 'admin-1', payload: { id: 'b' } });
    assert(p1.ok && p2.ok, '');
    await approveProposal(p1.proposal.id, 'admin-2');
    const pending = await listPendingProposals();
    eq(pending.length, 1, 'one pending');
    eq(pending[0].id, p2.proposal.id, 'p2 still pending');
  });

  if (failed > 0) { console.error(`\n✗ ${failed} check(s) failed\n`); process.exit(1); }
  console.log('\n✓ all four-eyes-approval checks passed\n');
})();

