1	/**
2	 * 4-eyes approval for high-stakes admin operations.
3	 *
4	 * Closes G5 from KNOWN-SECURITY-GAPS: a single platform admin can
5	 * currently export any tenant's audit pack with no second approver.
6	 * That's adequate for incident response under time pressure but
7	 * inadequate as a steady-state insider-threat preventive control.
8	 *
9	 * The pattern (inspired by GitHub branch-protection 4-eyes):
10	 *
11	 *   1. Initiator calls `proposeAction({ kind, requesterId, payload })`.
12	 *      Returns a proposalId in the `pending_approval` state.
13	 *   2. A SECOND admin (must NOT match `requesterId`) calls
14	 *      `approveProposal(proposalId, approverId)`.
15	 *   3. Once approved, the action is `ready_to_execute`. The initiator
16	 *      OR the approver can then call `executeProposal(proposalId)` to
17	 *      run it.
18	 *   4. Proposals expire after 24h with no approval.
19	 *   5. Every state transition writes an operator-integrity event so
20	 *      bypass attempts are auditable.
21	 *
22	 * Currently scoped to `regulator.exportPack`. Easy to extend to
23	 * `tenants.suspend`, `secrets.rotate`, `model-preferences.set` (model-
24	 * level), etc. — pass a different `kind`.
25	 *
26	 * Persistence: see AUDIT.md finding #4. Proposals previously lived in a
27	 * module-level `Map`, which meant a regulator-export proposal approved
28	 * before a deploy disappeared after the deploy. The `FourEyesStore`
29	 * interface below is the seam: production boot can register a DB-backed
30	 * store via `setFourEyesStore`. The default remains an in-memory Map so
31	 * existing tests stay unchanged.
32	 */
33	
34	import { randomUUID } from 'node:crypto';
35	
36	// ─── Types ──────────────────────────────────────────────────────────────────
37	
38	export type ProposalKind =
39	  | 'regulator.exportPack'
40	  | 'tenants.suspend'
41	  | 'secrets.rotate';
42	
43	export type ProposalState =
44	  | 'pending_approval'
45	  | 'ready_to_execute'
46	  | 'executed'
47	  | 'rejected'
48	  | 'expired';
49	
50	export interface Proposal<P = unknown> {
51	  id: string;
52	  kind: ProposalKind;
53	  requesterId: string;
54	  approverId?: string;
55	  payload: P;
56	  state: ProposalState;
57	  proposedAtMs: number;
58	  approvedAtMs?: number;
59	  executedAtMs?: number;
60	  rejectedAtMs?: number;
61	  rejectionReason?: string;
62	  expiresAtMs: number;
63	}
64	
65	export interface Failure { ok: false; reason: string }
66	export interface Success { ok: true; proposal: Proposal }
67	export type Result = Success | Failure;
68	
69	// ─── Storage ────────────────────────────────────────────────────────────────
70	
71	/**
72	 * Pluggable proposal store. Default impl below is an in-memory Map.
73	 * Production should wire a DB-backed store via `setFourEyesStore`. All
74	 * operations in this module go through `getFourEyesStore()` so the seam
75	 * is invisible to callers (bridge-router, tests).
76	 */
77	export interface FourEyesStore {
78	  get(id: string): Proposal | null | Promise<Proposal | null>;
79	  set(id: string, proposal: Proposal): void | Promise<void>;
80	  delete(id: string): void | Promise<void>;
81	  list(): Proposal[] | Promise<Proposal[]>;
82	  clear?(): void | Promise<void>;
83	}
84	
85	class InMemoryFourEyesStore implements FourEyesStore {
86	  private readonly proposals = new Map<string, Proposal>();
87	  get(id: string): Proposal | null { return this.proposals.get(id) ?? null; }
88	  set(id: string, p: Proposal): void { this.proposals.set(id, p); }
89	  delete(id: string): void { this.proposals.delete(id); }
90	  list(): Proposal[] { return [...this.proposals.values()]; }
91	  clear(): void { this.proposals.clear(); }
92	}
93	
94	let activeStore: FourEyesStore = new InMemoryFourEyesStore();
95	
96	/** Swap in a different store. Returns the previous one (useful in tests). */
97	export function setFourEyesStore(store: FourEyesStore): FourEyesStore {
98	  const prev = activeStore;
99	  activeStore = store;
100	  return prev;
101	}
102	
103	export function getFourEyesStore(): FourEyesStore { return activeStore; }
104	
105	const DEFAULT_EXPIRY_MS = 24 * 60 * 60 * 1000;  // 24h
106	
107	// ─── Audit hook ─────────────────────────────────────────────────────────────
108	// Every state transition fires this so the operator-integrity store
109	// captures the chain. Lazy-imported to avoid the dep cycle.
110	
111	async function emitAudit(p: Proposal, action: string): Promise<void> {
112	  try {
113	    const { recordOperatorEvent } = await import('./operator-integrity');
114	    // Dedicated audit kind: four-eyes transitions previously rode on
115	    // 'config_persona_set' (the closest existing kind), which also fed the
116	    // persona-misuse detector — so approval traffic polluted persona
117	    // analytics. Rows recorded under the old kind remain valid and readable.
118	    await recordOperatorEvent({
119	      tenantId: (p.payload as { tenantId?: string })?.tenantId ?? 'platform',
120	      kind: 'four_eyes_state_change',
121	      timestampMs: Date.now(),
122	      payload: {
123	        action: action as 'proposed' | 'approved' | 'rejected' | 'expired' | 'executed',
124	        proposalId: p.id,
125	        proposalKind: p.kind,
126	        requesterId: p.requesterId,
127	        approverId: p.approverId,
128	        state: p.state,
129	        description: `four-eyes ${action}: kind=${p.kind} proposal=${p.id} requester=${p.requesterId} approver=${p.approverId ?? '-'} state=${p.state}`,
130	      },
131	    });
132	  } catch {
133	    // metrics module unavailable in this runtime — skip
134	  }
135	}
136	
137	// ─── API ────────────────────────────────────────────────────────────────────
138	
139	export interface ProposeInput<P = unknown> {
140	  kind: ProposalKind;
141	  requesterId: string;
142	  payload: P;
143	  expiryMs?: number;
144	}
145	
146	export async function proposeAction<P = unknown>(input: ProposeInput<P>): Promise<Result> {
147	  if (!input.requesterId) return { ok: false, reason: 'requesterId required' };
148	  const id = randomUUID();
149	  const now = Date.now();
150	  const p: Proposal<P> = {
151	    id, kind: input.kind, requesterId: input.requesterId, payload: input.payload,
152	    state: 'pending_approval', proposedAtMs: now,
153	    expiresAtMs: now + (input.expiryMs ?? DEFAULT_EXPIRY_MS),
154	  };
155	  await activeStore.set(id, p as Proposal);
156	  await emitAudit(p as Proposal, 'proposed');
157	  return { ok: true, proposal: p as Proposal };
158	}
159	
160	export async function approveProposal(proposalId: string, approverId: string): Promise<Result> {
161	  if (!approverId) return { ok: false, reason: 'approverId required' };
162	  const p = await activeStore.get(proposalId);
163	  if (!p) return { ok: false, reason: 'proposal not found' };
164	  if (p.state !== 'pending_approval') return { ok: false, reason: `proposal in state ${p.state}, not pending_approval` };
165	  if (Date.now() > p.expiresAtMs) {
166	    p.state = 'expired';
167	    await activeStore.set(p.id, p);
168	    await emitAudit(p, 'expired');
169	    return { ok: false, reason: 'proposal expired' };
170	  }
171	  if (approverId === p.requesterId) return { ok: false, reason: 'approverId must differ from requesterId (4-eyes rule)' };
172	  p.approverId = approverId;
173	  p.approvedAtMs = Date.now();
174	  p.state = 'ready_to_execute';
175	  await activeStore.set(p.id, p);
176	  await emitAudit(p, 'approved');
177	  return { ok: true, proposal: p };
178	}
179	
180	export async function rejectProposal(proposalId: string, approverId: string, reason: string): Promise<Result> {
181	  const p = await activeStore.get(proposalId);
182	  if (!p) return { ok: false, reason: 'proposal not found' };
183	  if (p.state !== 'pending_approval') return { ok: false, reason: `proposal in state ${p.state}` };
184	  if (approverId === p.requesterId) return { ok: false, reason: 'approverId must differ from requesterId' };
185	  p.state = 'rejected';
186	  p.rejectedAtMs = Date.now();
187	  p.rejectionReason = reason;
188	  p.approverId = approverId;
189	  await activeStore.set(p.id, p);
190	  await emitAudit(p, 'rejected');
191	  return { ok: true, proposal: p };
192	}
193	
194	export async function executeProposal(proposalId: string, executorId: string): Promise<Result> {
195	  const p = await activeStore.get(proposalId);
196	  if (!p) return { ok: false, reason: 'proposal not found' };
197	  if (p.state !== 'ready_to_execute') return { ok: false, reason: `proposal in state ${p.state}, not ready_to_execute` };
198	  if (Date.now() > p.expiresAtMs) {
199	    p.state = 'expired';
200	    await activeStore.set(p.id, p);
201	    await emitAudit(p, 'expired');
202	    return { ok: false, reason: 'proposal expired before execution' };
203	  }
204	  // executor must be either requester or approver
205	  if (executorId !== p.requesterId && executorId !== p.approverId) {
206	    return { ok: false, reason: 'executorId must be requester or approver' };
207	  }
208	  p.state = 'executed';
209	  p.executedAtMs = Date.now();
210	  await activeStore.set(p.id, p);
211	  await emitAudit(p, 'executed');
212	  return { ok: true, proposal: p };
213	}
214	
215	export async function getProposal(proposalId: string): Promise<Proposal | null> {
216	  return (await activeStore.get(proposalId)) ?? null;
217	}
218	
219	export async function listPendingProposals(): Promise<Proposal[]> {
220	  const all = await activeStore.list();
221	  return all.filter((p) => p.state === 'pending_approval');
222	}
223	
224	export async function clearProposalsForTesting(): Promise<void> {
225	  if (activeStore.clear) {
226	    await activeStore.clear();
227	    return;
228	  }
229	  // Fallback for stores without an explicit clear: delete each.
230	  const all = await activeStore.list();
231	  for (const p of all) await activeStore.delete(p.id);
232	}
233	
234	// ─── Sweeper for expired proposals ──────────────────────────────────────────
235	
236	export async function sweepExpiredProposals(now = Date.now()): Promise<number> {
237	  let n = 0;
238	  const all = await activeStore.list();
239	  for (const p of all) {
240	    if ((p.state === 'pending_approval' || p.state === 'ready_to_execute') && now > p.expiresAtMs) {
241	      p.state = 'expired';
242	      await activeStore.set(p.id, p);
243	      await emitAudit(p, 'expired');
244	      n++;
245	    }
246	  }
247	  return n;
248	}
