 * module-level `Map`, which meant a regulator-export proposal approved
 * before a deploy disappeared after the deploy. The `FourEyesStore`
 * interface below is the seam: production boot can register a DB-backed
 * store via `setFourEyesStore`. The default remains an in-memory Map so
 * existing tests stay unchanged.
 */

import { randomUUID } from 'node:crypto';

// ─── Types ──────────────────────────────────────────────────────────────────

export type ProposalKind =
  | 'regulator.exportPack'
  | 'tenants.suspend'
  | 'secrets.rotate';

export type ProposalState =
  | 'pending_approval'
  | 'ready_to_execute'
  | 'executed'
  | 'rejected'
  | 'expired';

export interface Proposal<P = unknown> {
  id: string;
  kind: ProposalKind;
  requesterId: string;
  approverId?: string;
  payload: P;
  state: ProposalState;
  proposedAtMs: number;
  approvedAtMs?: number;
  executedAtMs?: number;
  rejectedAtMs?: number;
  rejectionReason?: string;
  expiresAtMs: number;
}

export interface Failure { ok: false; reason: string }
export interface Success { ok: true; proposal: Proposal }
export type Result = Success | Failure;

// ─── Storage ────────────────────────────────────────────────────────────────

/**
 * Pluggable proposal store. Default impl below is an in-memory Map.
 * Production should wire a DB-backed store via `setFourEyesStore`. All
 * operations in this module go through `getFourEyesStore()` so the seam
 * is invisible to callers (bridge-router, tests).
 */
export interface FourEyesStore {
  get(id: string): Proposal | null | Promise<Proposal | null>;
  set(id: string, proposal: Proposal): void | Promise<void>;
  delete(id: string): void | Promise<void>;
  list(): Proposal[] | Promise<Proposal[]>;
  clear?(): void | Promise<void>;
}

class InMemoryFourEyesStore implements FourEyesStore {
  private readonly proposals = new Map<string, Proposal>();
  get(id: string): Proposal | null { return this.proposals.get(id) ?? null; }
  set(id: string, p: Proposal): void { this.proposals.set(id, p); }
  delete(id: string): void { this.proposals.delete(id); }
  list(): Proposal[] { return [...this.proposals.values()]; }
  clear(): void { this.proposals.clear(); }
}

let activeStore: FourEyesStore = new InMemoryFourEyesStore();

/** Swap in a different store. Returns the previous one (useful in tests). */
export function setFourEyesStore(store: FourEyesStore): FourEyesStore {
  const prev = activeStore;
  activeStore = store;
  return prev;
}

export function getFourEyesStore(): FourEyesStore { return activeStore; }

const DEFAULT_EXPIRY_MS = 24 * 60 * 60 * 1000;  // 24h

// ─── Audit hook ─────────────────────────────────────────────────────────────
// Every state transition fires this so the operator-integrity store
// captures the chain. Lazy-imported to avoid the dep cycle.

async function emitAudit(p: Proposal, action: string): Promise<void> {
  try {
    const { recordOperatorEvent } = await import('./operator-integrity');
    // Dedicated audit kind: four-eyes transitions previously rode on
    // 'config_persona_set' (the closest existing kind), which also fed the
    // persona-misuse detector — so approval traffic polluted persona
    // analytics. Rows recorded under the old kind remain valid and readable.
    await recordOperatorEvent({
      tenantId: (p.payload as { tenantId?: string })?.tenantId ?? 'platform',
      kind: 'four_eyes_state_change',
      timestampMs: Date.now(),
      payload: {
        action: action as 'proposed' | 'approved' | 'rejected' | 'expired' | 'executed',
        proposalId: p.id,
        proposalKind: p.kind,
        requesterId: p.requesterId,
        approverId: p.approverId,
        state: p.state,
        description: `four-eyes ${action}: kind=${p.kind} proposal=${p.id} requester=${p.requesterId} approver=${p.approverId ?? '-'} state=${p.state}`,
      },
    });
  } catch {
    // metrics module unavailable in this runtime — skip
  }
}

// ─── API ────────────────────────────────────────────────────────────────────

export interface ProposeInput<P = unknown> {
  kind: ProposalKind;
  requesterId: string;
  payload: P;
  expiryMs?: number;
}

export async function proposeAction<P = unknown>(input: ProposeInput<P>): Promise<Result> {
  if (!input.requesterId) return { ok: false, reason: 'requesterId required' };
  const id = randomUUID();
  const now = Date.now();
  const p: Proposal<P> = {
    id, kind: input.kind, requesterId: input.requesterId, payload: input.payload,
    state: 'pending_approval', proposedAtMs: now,
    expiresAtMs: now + (input.expiryMs ?? DEFAULT_EXPIRY_MS),
  };
  await activeStore.set(id, p as Proposal);
  await emitAudit(p as Proposal, 'proposed');
  return { ok: true, proposal: p as Proposal };
}

export async function approveProposal(proposalId: string, approverId: string): Promise<Result> {
  if (!approverId) return { ok: false, reason: 'approverId required' };
  const p = await activeStore.get(proposalId);
  if (!p) return { ok: false, reason: 'proposal not found' };
  if (p.state !== 'pending_approval') return { ok: false, reason: `proposal in state ${p.state}, not pending_approval` };
  if (Date.now() > p.expiresAtMs) {
    p.state = 'expired';
    await activeStore.set(p.id, p);
    await emitAudit(p, 'expired');
    return { ok: false, reason: 'proposal expired' };
  }
  if (approverId === p.requesterId) return { ok: false, reason: 'approverId must differ from requesterId (4-eyes rule)' };
  p.approverId = approverId;
  p.approvedAtMs = Date.now();
  p.state = 'ready_to_execute';
  await activeStore.set(p.id, p);
  await emitAudit(p, 'approved');
  return { ok: true, proposal: p };
}

export async function rejectProposal(proposalId: string, approverId: string, reason: string): Promise<Result> {
  const p = await activeStore.get(proposalId);
  if (!p) return { ok: false, reason: 'proposal not found' };
  if (p.state !== 'pending_approval') return { ok: false, reason: `proposal in state ${p.state}` };
  if (approverId === p.requesterId) return { ok: false, reason: 'approverId must differ from requesterId' };
  p.state = 'rejected';
  p.rejectedAtMs = Date.now();
  p.rejectionReason = reason;
  p.approverId = approverId;
  await activeStore.set(p.id, p);
  await emitAudit(p, 'rejected');
  return { ok: true, proposal: p };
}

export async function executeProposal(proposalId: string, executorId: string): Promise<Result> {
  const p = await activeStore.get(proposalId);
  if (!p) return { ok: false, reason: 'proposal not found' };
  if (p.state !== 'ready_to_execute') return { ok: false, reason: `proposal in state ${p.state}, not ready_to_execute` };
  if (Date.now() > p.expiresAtMs) {
    p.state = 'expired';
    await activeStore.set(p.id, p);
    await emitAudit(p, 'expired');
    return { ok: false, reason: 'proposal expired before execution' };
  }
  // executor must be either requester or approver
  if (executorId !== p.requesterId && executorId !== p.approverId) {
    return { ok: false, reason: 'executorId must be requester or approver' };
  }
  p.state = 'executed';
  p.executedAtMs = Date.now();
  await activeStore.set(p.id, p);
  await emitAudit(p, 'executed');
  return { ok: true, proposal: p };
}

export async function getProposal(proposalId: string): Promise<Proposal | null> {
  return (await activeStore.get(proposalId)) ?? null;
}

export async function listPendingProposals(): Promise<Proposal[]> {
  const all = await activeStore.list();
  return all.filter((p) => p.state === 'pending_approval');
}

export async function clearProposalsForTesting(): Promise<void> {
  if (activeStore.clear) {
    await activeStore.clear();
    return;
  }
  // Fallback for stores without an explicit clear: delete each.
  const all = await activeStore.list();
  for (const p of all) await activeStore.delete(p.id);
}

// ─── Sweeper for expired proposals ──────────────────────────────────────────

export async function sweepExpiredProposals(now = Date.now()): Promise<number> {
  let n = 0;
  const all = await activeStore.list();
  for (const p of all) {
    if ((p.state === 'pending_approval' || p.state === 'ready_to_execute') && now > p.expiresAtMs) {
      p.state = 'expired';
      await activeStore.set(p.id, p);
      await emitAudit(p, 'expired');
      n++;
    }
  }
  return n;
}

