    const p2 = await proposeAction({ kind: 'regulator.exportPack', requesterId: 'admin-1', payload: { id: 'b' } });
    assert(p1.ok && p2.ok, '');
    await approveProposal(p1.proposal.id, 'admin-2');
    const pending = await listPendingProposals();
    eq(pending.length, 1, 'one pending');
    eq(pending[0].id, p2.proposal.id, 'p2 still pending');
  });

  if (failed > 0) { console.error(`\n✗ ${failed} check(s) failed\n`); process.exit(1); }
  console.log('\n✓ all four-eyes-approval checks passed\n');
})();

